// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor, uint256 warp) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount <= 1000 ether);
        vm.assume(warp > 0 && warp < 1_000_000);
        vm.warp(block.timestamp + warp);
        vm.deal(actor, amount + 1 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        bool expected = (amount == 10 ether);
        assertTrue(ok == expected);
    }
}
